// List of units to analyze
const units = ['CS-01', 'CS-02', 'CS-03'];

// Create a message for each unit
const messages = units.map(unitId => {
    return {
        payload: unitId,
        unitId: unitId
    };
});

return [messages];

const unitId = msg.unitId;

// Flux query to get temperature trend over last hour
const query = `
from(bucket: "cold_storage")
  |> range(start: -1h)
  |> filter(fn: (r) => r["_measurement"] == "sensor_data")
  |> filter(fn: (r) => r["unitId"] == "${unitId}")
  |> filter(fn: (r) => r["_field"] == "temperature")
  |> derivative(unit: 1h, nonNegative: false)
  |> mean()
`;

msg.payload = query;
msg.analysis = 'temperature_trend';

return msg;

const unitId = msg.unitId;

// Flux query to get energy consumption trend
const query = `
from(bucket: "cold_storage")
  |> range(start: -1h)
  |> filter(fn: (r) => r["_measurement"] == "sensor_data")
  |> filter(fn: (r) => r["unitId"] == "${unitId}")
  |> filter(fn: (r) => r["_field"] == "energyConsumption")
  |> derivative(unit: 1h, nonNegative: false)
  |> mean()
`;

msg.payload = query;
msg.analysis = 'energy_trend';

return msg;

const unitId = msg.unitId;

// Flux query to calculate compressor ON percentage
const query = `
import "strings"

data = from(bucket: "cold_storage")
  |> range(start: -1h)
  |> filter(fn: (r) => r["_measurement"] == "sensor_data")
  |> filter(fn: (r) => r["unitId"] == "${unitId}")
  |> filter(fn: (r) => r["_field"] == "compressorStatus")

total = data |> count() |> findRecord(fn: (key) => true, idx: 0)

on_count = data 
  |> filter(fn: (r) => r["_value"] == "ON")
  |> count()
  |> findRecord(fn: (key) => true, idx: 0)

data
  |> limit(n: 1)
  |> map(fn: (r) => ({
      _time: r._time,
      _measurement: "compressor_runtime",
      _field: "on_percentage",
      _value: float(v: on_count._value) / float(v: total._value) * 100.0
  }))
`;

msg.payload = query;
msg.analysis = 'compressor_runtime';

return msg;

// Store query results by analysis type
const unitId = msg.unitId;
const analysisType = msg.analysis;
const query = msg.payload;

// Get or initialize unit analysis context
let unitAnalysis = context.get(unitId) || {};

// Simulate query execution - in real implementation, use HTTP request to InfluxDB
// For now, store query and mark as pending
unitAnalysis[analysisType] = {
    query: query,
    result: null,
    timestamp: Date.now()
};

context.set(unitId, unitAnalysis);

// Pass message forward with query info
msg.queryInfo = {
    unitId: unitId,
    analysis: analysisType,
    query: query
};

return msg;

// Wait for all three queries to complete for this unit
const unitId = msg.unitId;

// Get stored results
let results = flow.get('pm_results') || {};
if (!results[unitId]) {
    results[unitId] = {
        temperature_trend: null,
        energy_trend: null,
        compressor_runtime: null,
        timestamp: Date.now()
    };
}

// Store this result
results[unitId][msg.analysis] = msg.queryInfo;

flow.set('pm_results', results);

// Check if all three analyses are complete
if (results[unitId].temperature_trend && 
    results[unitId].energy_trend && 
    results[unitId].compressor_runtime) {

    // All results ready - proceed to maintenance score calculation
    msg.payload = {
        unitId: unitId,
        analyses: results[unitId]
    };

    // Clear results for next cycle
    delete results[unitId];
    flow.set('pm_results', results);

    return msg;
}

return null;

const unitId = msg.payload.unitId;

// Simulated trend values (in real implementation, these come from InfluxDB queries)
// For demonstration, we'll calculate based on recent data patterns

// Get recent data from context to simulate trend analysis
const recentData = context.get(`${unitId}_recent`) || {
    temperatures: [4.0, 4.1, 4.2, 4.3, 4.4],
    energies: [2.1, 2.2, 2.3, 2.4, 2.5],
    compressor_on_pct: 60
};

// Calculate temperature stability score (0-100)
// Lower score = more unstable = higher maintenance need
const temps = recentData.temperatures;
const tempMean = temps.reduce((a, b) => a + b) / temps.length;
const tempVariance = temps.reduce((sum, val) => sum + Math.pow(val - tempMean, 2), 0) / temps.length;
const tempStdDev = Math.sqrt(tempVariance);

// Temperature stability: low variance = high score
let tempStabilityScore = Math.max(0, Math.min(100, 100 - (tempStdDev * 50)));

// Check for rising trend
const tempTrend = temps[temps.length - 1] - temps[0];
if (tempTrend > 0.5) {
    tempStabilityScore -= 20; // Penalize rising trend
}

// Calculate energy efficiency score (0-100)
const energies = recentData.energies;
const energyMean = energies.reduce((a, b) => a + b) / energies.length;

// Energy efficiency: lower consumption = higher score
let energyEfficiencyScore = Math.max(0, Math.min(100, 100 - ((energyMean - 2.0) * 25)));

// Check for increasing energy trend
const energyTrend = energies[energies.length - 1] - energies[0];
if (energyTrend > 0.3) {
    energyEfficiencyScore -= 15; // Penalize rising energy
}

// Calculate compressor health score (0-100)
const compressorOnPct = recentData.compressor_on_pct;

// Ideal compressor runtime is 40-60%
// Too low or too high indicates problems
let compressorHealthScore = 100;
if (compressorOnPct < 40) {
    compressorHealthScore = 60 + compressorOnPct; // Low runtime
} else if (compressorOnPct > 60) {
    compressorHealthScore = 100 - (compressorOnPct - 60); // High runtime
}

// Calculate overall maintenance score (0-100)
// Higher score = more maintenance attention needed
const maintenanceScore = Math.round(
    (100 - tempStabilityScore) * 0.35 +
    (100 - energyEfficiencyScore) * 0.35 +
    (100 - compressorHealthScore) * 0.30
);

// Determine priority and recommendation
let priority, recommendation;

if (maintenanceScore < 20) {
    priority = 'low';
    recommendation = 'Normal operation - routine maintenance only';
} else if (maintenanceScore < 40) {
    priority = 'low';
    recommendation = 'Monitor trends - no immediate action needed';
} else if (maintenanceScore < 60) {
    priority = 'medium';
    recommendation = 'Schedule inspection within 2 weeks';
} else if (maintenanceScore < 80) {
    priority = 'high';
    recommendation = 'Schedule maintenance within 48 hours';
} else {
    priority = 'critical';
    recommendation = 'Immediate maintenance required - equipment degradation detected';
}

// Detailed analysis
const analysis = {
    unitId: unitId,
    maintenanceScore: maintenanceScore,
    temperatureStability: Math.round(tempStabilityScore),
    energyEfficiency: Math.round(energyEfficiencyScore),
    compressorHealth: Math.round(compressorHealthScore),
    recommendation: recommendation,
    priority: priority,
    timestamp: new Date().toISOString(),
    details: {
        temperatureTrend: tempTrend > 0.3 ? 'increasing' : tempTrend < -0.3 ? 'decreasing' : 'stable',
        energyTrend: energyTrend > 0.2 ? 'increasing' : energyTrend < -0.2 ? 'decreasing' : 'stable',
        compressorRuntime: `${compressorOnPct}%`,
        averageTemperature: Math.round(tempMean * 10) / 10,
        averageEnergy: Math.round(energyMean * 10) / 10
    }
};

msg.payload = analysis;
msg.unitId = unitId;
msg.maintenanceScore = maintenanceScore;
msg.priority = priority;

return msg;

const analysis = msg.payload;
const unitId = analysis.unitId;

// Prepare Ditto update for maintenance feature
const dittoPayload = {
    features: {
        maintenance: {
            properties: {
                score: analysis.maintenanceScore,
                temperatureStability: analysis.temperatureStability,
                energyEfficiency: analysis.energyEfficiency,
                compressorHealth: analysis.compressorHealth,
                recommendation: analysis.recommendation,
                priority: analysis.priority,
                lastCalculated: analysis.timestamp
            }
        },
        status: {
            properties: {
                healthScore: Math.round((analysis.temperatureStability + analysis.energyEfficiency + analysis.compressorHealth) / 3),
                health: analysis.priority === 'critical' ? 'critical' :
                        analysis.priority === 'high' ? 'attention' : 'healthy'
            }
        }
    }
};

msg.payload = dittoPayload;
msg.url = `http://ditto-gateway:8080/api/2/things/org.eclipse.ditto:${unitId}`;
msg.method = 'PATCH';
msg.headers = {
    'Content-Type': 'application/merge-patch+json'
};

return msg;

const analysis = msg.payload;

// Generate predictive maintenance alert if score is above threshold
if (analysis.maintenanceScore >= 60) {

    const alert = {
        unitId: analysis.unitId,
        alertType: 'predictive_maintenance',
        severity: analysis.priority === 'critical' ? 'critical' : 'warning',
        message: `Predictive maintenance alert: ${analysis.recommendation}`,
        maintenanceScore: analysis.maintenanceScore,
        details: analysis.details,
        timestamp: analysis.timestamp
    };

    msg.payload = alert;
    msg.topic = `coldstorage/${analysis.unitId}/alerts`;

    return msg;
}

return null;

const alert = msg.payload;

const measurement = 'maintenance_score';
const tags = `unitId=${alert.unitId},priority=${alert.details.priority || 'high'}`;
const fields = [
    `score=${alert.maintenanceScore}`,
    `message="${alert.message}"`,
    `recommendation="${alert.details.recommendation || 'Check equipment'}"`
].join(',');

const timestampNs = new Date(alert.timestamp).getTime() * 1000000;

msg.payload = `${measurement},${tags} ${fields} ${timestampNs}`;
msg.bucket = 'analytics';

return msg;
